CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,name TEXT,role TEXT,facility TEXT,salt TEXT,password_hash TEXT);
        CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires REAL);
        CREATE TABLE IF NOT EXISTS patients(id INTEGER PRIMARY KEY,external_id TEXT,source TEXT,name TEXT,facility TEXT,age REAL,sex TEXT,regimen TEXT,treatment_line INTEGER,viral_load REAL,adherence REAL,assigned_to INTEGER REFERENCES users(id),notes TEXT DEFAULT '',original_json TEXT,created_at TEXT,UNIQUE(source,external_id));
        CREATE TABLE IF NOT EXISTS episodes(id INTEGER PRIMARY KEY,patient_id INTEGER UNIQUE REFERENCES patients(id),referred_at TEXT,sample_at TEXT,sample_type TEXT,dbs_reason TEXT DEFAULT '',lab_owner INTEGER REFERENCES users(id),status TEXT DEFAULT 'Not collected',failure_reason TEXT DEFAULT '',report_at TEXT,amplified INTEGER,mutations TEXT DEFAULT '',repeat_requested_at TEXT,reviewed_at TEXT,reviewer INTEGER REFERENCES users(id),decision TEXT,decision_at TEXT,decision_notes TEXT DEFAULT '',recommended_regimen TEXT DEFAULT '',implemented_at TEXT,implementation_notes TEXT DEFAULT '',version INTEGER DEFAULT 0,discussion_status TEXT DEFAULT '');
        CREATE TABLE IF NOT EXISTS discussions(id INTEGER PRIMARY KEY,patient_id INTEGER REFERENCES patients(id),author INTEGER REFERENCES users(id),body TEXT,created_at TEXT);
        CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor TEXT,role TEXT,action TEXT,entity TEXT,before_json TEXT,after_json TEXT,created_at TEXT);
        CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
